{
  "no_answer": false,
  "sentences": [
    {
      "text": "A device identifier is a mandatory, fixed portion of a UDI that identifies the specific version or model of a device and the labeler of that device.",
      "sources": [
        1,
        2,
        3,
        4,
        5
      ]
    },
    {
      "text": "A production identifier is a conditional, variable portion of a UDI that identifies one or more of the following when included on the label of the device: (i) The lot or batch within which a device was manufactured; (ii) The serial number of a specific device; (iii) The expiration date of a specific device; (iv) The date a specific device was manufactured.",
      "sources": [
        1,
        2,
        3,
        4,
        5
      ]
    }
  ]
}

{
  "no_answer": false,
  "sentences": [
    {
      "text": "Adequate directions for use means directions under which the layman can use a device safely and for the purposes for which it is intended.",
      "sources": [
        2
      ]
    }
  ]
}

{
  "no_answer": false,
