    {
      "text": "Devices containing natural rubber latex that contacts humans, as described in paragraph (b) of this section, shall bear the following statement in bold print on the device labeling: ‘Caution: This Product Contains Natural Rubber Latex Which May Cause Allergic Reactions.’",
      "sources": [
        1,
        2,
        3
      ]
    }
  ]
}

